# GF(2^128) helpers in GCM bit order, using normal-polynomial arithmetic internally
_M = [sum(1 << b for b in range(i, 128, 6)) for i in range(6)]
_PM = [sum(1 << b for b in range(i, 256, 6)) for i in range(6)]
_REV8 = bytes(int(f"{i:08b}"[::-1], 2) for i in range(256))
_P = (1 << 128) | 0x87


def rev(x):
    return int.from_bytes(x.to_bytes(16, "little").translate(_REV8), "big")


def clmul(a, b):
    A = [a & m for m in _M]
    B = [b & m for m in _M]
    r = 0
    for k in range(6):
        s = 0
        for i in range(6):
            s ^= 0  # placeholder
        r = r
    res = 0
    for i in range(6):
        ai = A[i]
        if not ai:
            continue
        for j in range(6):
            res ^= (ai * B[j]) & _PM[(i + j) % 6]
    return res


def red(p):
    hi = p >> 128
    p = (p & ((1 << 128) - 1)) ^ hi ^ (hi << 1) ^ (hi << 2) ^ (hi << 7)
    hi = p >> 128
    if hi:
        p = (p & ((1 << 128) - 1)) ^ hi ^ (hi << 1) ^ (hi << 2) ^ (hi << 7)
    return p


def nmul(a, b):
    return red(clmul(a, b))


def ninv(a):
    # extended Euclid over GF(2)[x]
    u, v = a, _P
    g1, g2 = 1, 0
    while u != 1:
        j = u.bit_length() - v.bit_length()
        if j < 0:
            u, v = v, u
            g1, g2 = g2, g1
            j = -j
        u ^= v << j
        g1 ^= g2 << j
    return red(g1) if g1.bit_length() > 128 else g1


def npow(h, e):
    r = 1
    b = h
    while e:
        if e & 1:
            r = nmul(r, b)
        e >>= 1
        if e:
            b = nmul(b, b)
    return r
